"""Original bilingual setup tutorials, supported by recorded primary sources."""
import json,pathlib
R=pathlib.Path(__file__).resolve().parents[1]
def p(mn,en):return ({'type':'p','text':mn},{'type':'p','text':en})
def code(text,lang='Text'):return ({'type':'code','language':lang,'text':text},{'type':'code','language':lang,'text':text})
def listing(mn,en):return ({'type':'list','items':mn},{'type':'list','items':en})
def diagram(caption,en,nodes,edges):
 def make(cap):return {'type':'diagram','kind':'graph','directed':True,'nodes':[{'id':str(i),'label':t,'x':x,'y':y}for i,(t,x,y)in enumerate(nodes)],'edges':[[str(a),str(b)]for a,b in edges],'caption':cap}
 return make(caption),make(en)
def image(name,mn,en):
 def b(alt):return {'type':'image','assetPath':'tutorial-assets/cpp-environment/'+name+'.webp','alt':alt,'caption':'Microsoft VS Code docs · CC BY3.0 US. Албан screenshot; зөвхөн WebP болгосон. UI/version нь одоогийнхоос ялгаатай байж болно. / Official screenshot, re-encoded only; UI/version may differ.','align':'center','width':100}
 return b(mn),b(en)
def dev_image():
 def b(alt):return {'type':'image','assetPath':'tutorial-assets/cpp-environment/devcpp-historical.webp','alt':alt,'caption':'Dev-C++ 5.1.1.0 (2012) · AsbakWiki · CC BY-SA3.0. Historical screenshot, re-encoded to WebP; not Embarcadero6.3 settings.','align':'center','width':100}
 return b('Dev-C++5.1.1.0-ийн түүхэн interface; дээрээ Tools, Execute menu-тэй'),b('Historical Dev-C++5.1.1.0 interface showing Tools and Execute menus')
def section(mn,en,*blocks):return ({'title':mn,'blocks':[b[0]for b in blocks]},{'title':en,'blocks':[b[1]for b in blocks]})
def links(items):return ({'type':'links','items':[{'label':a,'url':u}for a,u in items]},{'type':'links','items':[{'label':a,'url':u}for a,u in items]})
def lesson(id,mn,en,summary,summaryEn,sections,related):
 return {'id':id,'order':1,'category':'C++ орчин','levelKey':'beginner','priorityLevel':'high','title':mn,'summary':summary,'related':related,'automaticDemo':False,'sections':[s[0]for s in sections],'translations':{'en':{'title':en,'summary':summaryEn,'sections':[s[1]for s in sections]}}}
probe='#include <iostream>\n\nint main() {\n    std::cout << __cplusplus << \'\\n\';\n}\n'
sumcode='#include <iostream>\n\nusing namespace std;\n\nint main() {\n    int a, b;\n    cin >> a >> b;\n    cout << a + b << \'\\n\';\n}\n'
win=lesson('cpp-windows-vscode','Windows дээр VS Code, terminal, C++','Windows: VS Code, terminal and C++','Нэг practice folder-оос C++17 программаа compile/run хийх; CMD, PowerShell, UCRT64 Bash-ийг ялгах.','Compile/run a C++17 program from one practice folder; distinguish CMD, PowerShell and UCRT64 Bash.',[
 section('1. Editor, terminal, shell, compiler','1. Editor, terminal, shell and compiler',
 p('VS Code нь editor. Integrated Terminal бол shell ажиллах самбар; shell нь командыг тайлбарлана. g++ бол C++-ийг executable болгох compiler. C/C++ extension суулгах нь g++ суулгасан гэсэн үг биш. Энэ заавар Visual Studio IDE биш, VS Code-д зориулагдсан.','VS Code is an editor. Its integrated terminal hosts a shell that interprets commands. g++ compiles C++ into an executable. Installing the C/C++ extension does not install g++. This guide is for VS Code, not the Visual Studio IDE.'),
 diagram('Нэг эх кодоос ажиллах программ хүртэл','From source to a running program',[('main.cpp',15,50),('g++',50,50),('a.exe',85,50)],[(0,1),(1,2)]),
 p('Эхлэгчийн богино зам: MSYS2 UCRT64-ийн compiler-ийг суулгаад, VS Code дотор Command Prompt (CMD) ашигла. CMD нь <, > file redirection-ийг шууд дэмждэг. Linux-тэй ойр дасгал хийх бол сүүлд UCRT64 Bash сонго. PowerShell мөн compiler ажиллуулж чадна; харин input redirection нь өөр. Windows Terminal тусдаа суулгах шаардлагагүй.','A short beginner path: install the MSYS2 UCRT64 compiler and use Command Prompt (CMD) inside VS Code. CMD supports < and > file redirection directly. Choose UCRT64 Bash later for Linux-like practice. PowerShell can also invoke the compiler, but input redirection differs. A separate Windows Terminal installation is unnecessary.')),
 section('2. Албан toolchain суулгах','2. Install the official toolchain',
 p('VS Code болон Microsoft-ийн C/C++ extension-ийг албан эхээс суулга. Доорх зурагт extension-ийн publisher ба Install товч харагдана; зураг дахь хуучин version-ийг зориуд сонгох шаардлагагүй.','Install VS Code and Microsoft’s C/C++ extension from official sources. The image identifies the publisher and Install button; you need not install the historical version shown.'),image('cpp-extension','Microsoft C/C++ extension-ийн publisher, Install товч','Microsoft C/C++ extension publisher and Install button'),
 p('MSYS2-ийн албан installer-ийг ашигла. Одоогийн заавар 64-bit Windows10/11-д UCRT64 орчныг сонгодог. MSYS2 UCRT64 terminal-ийг нээж бүх update-ийг хий. Core update terminal-аа хаахыг хүсвэл зөвшөөрөөд дахин нээж update-ийг давт.','Use the official MSYS2 installer. The current Windows10/11 64-bit workflow uses UCRT64. Open its terminal and perform a full update. If a core update asks to close the terminal, reopen it and repeat the update.'),
 code('pacman -Suy\npacman -S --needed base-devel mingw-w64-ucrt-x86_64-toolchain\n'),
 image('msys2-toolchain','UCRT64 toolchain group-ийг суулгах MSYS2 terminal-ийн албан зураг','Official MSYS2 terminal screenshot installing the UCRT64 toolchain group'),
 p('Package list зурагтай яг адил байх албагүй. Default group-ийг Enter-ээр сонгож, install prompt-ийг унш. PATH-д default суулгасан бол C:\\msys64\\ucrt64\\bin нэмнэ. C:\\msys64\\usr\\bin-ийг Windows compiler PATH гэж бүү андуур. Шинэ PATH авахын тулд terminal болон VS Code-оо дахин нээ.','The package list may differ from the image. Select the default group with Enter and read the installation prompt. For the default install, add C:\\msys64\\ucrt64\\bin to the Windows user PATH. Do not confuse C:\\msys64\\usr\\bin with the native Windows compiler location. Reopen terminals and VS Code after changing PATH.')),
 section('3. Аль folder дээр ажиллаж байна вэ?','3. Which folder are you working in?',
 p('Terminal → Select Default Profile → Command Prompt сонгоод шинэ terminal нээ. Командуудыг тус тусад нь ажиллуул. mkdir practice нь одоогийн folder дотор practice үүсгэнэ. code practice нь тэр folder-ийг VS Code-д нээнэ; эх terminal-ийн folder-ийг өөрчлөхгүй. cd practice нь харин эх terminal-ийг дотор нь оруулна.','Choose Terminal → Select Default Profile → Command Prompt, then open a new terminal. Run the commands separately. mkdir practice creates a directory inside the current one. code practice opens it in VS Code but does not change the originating shell’s directory. cd practice changes that shell’s directory.'),
 code('mkdir practice\ncode practice\ncd practice\ncd\ncode .\n'),
 p('CMD-ийн cd дангаараа одоогийн замыг харуулна. code . нь одоогийн folder-ийг VS Code-д нээнэ. Шинээр нээгдсэн workspace-ийн Terminal → New Terminal ихэнхдээ тэр folder-оос эхэлнэ; terminal.integrated.cwd зэрэг тохиргоогоор өөр байж болох тул замаа шалга. Зайтай нэрийг quote хийнэ: mkdir "CP Practice", cd "CP Practice". Өөр drive руу орох бол cd /d "D:\\CP Practice".','In CMD, cd alone prints the current path. code . opens that directory in VS Code. Terminal → New Terminal in the opened workspace normally starts there, though settings such as terminal.integrated.cwd can override it; check the path. Quote names containing spaces: mkdir "CP Practice", cd "CP Practice". To change drive, use cd /d "D:\\CP Practice".'),
 p('code танигдахгүй бол VS Code-ийг нээгээд File → Open Folder-оор practice-ийг сонго. Windows installer-ийн Add to PATH сонголт, шинэ terminal ашиглаж байгаа эсэхээ шалга; compiler эсвэл VS Code-ийг санамсаргүй сайтаас дахин татах хэрэггүй.','If code is not found, open VS Code and use File → Open Folder for practice. Check the Windows installer’s Add to PATH option and use a fresh terminal; do not fetch replacement tools from random sites.')),
 section('4. Compile ба run хоёр өөр алхам','4. Compilation and execution are different',
 p('Explorer дээр main.cpp үүсгэж хадгал. Доорх нь compiler-ийн language mode-ийг хэвлэнэ. #include нь stream-ийг авчирна; main нь эхлэх функц; __cplusplus нь сонгосон стандартын тоон macro.','Create and save main.cpp in Explorer. This probe prints the compiler’s selected language mode. #include supplies streams; main is the entry point; __cplusplus is the numeric language-mode macro.'),code(probe,'C++17'),
 code('where g++\ng++ --version\ng++ -std=c++17 -O2 -Wall -Wextra main.cpp -o a.exe\na.exe\n'),
 p('where g++ нь PATH-аас олсон хувилбаруудыг харуулна. -std=c++17 нь build-ийн горим; -O2 нь optimization; -Wall -Wextra нь анхааруулга; -o a.exe нь executable-ийн нэр. C++17 mode-д 201703 гарна. Шинэ compiler C++20 дэмждэг бол -std=c++20 горимд 202002 гарч болно; macro нь бүх language/library feature бүрэн хэрэгжсэн баталгаа биш. Compile алдаатай бол хуучин a.exe-г ажиллуулаад шинэ код амжилттай гэж бүү үз.','where g++ lists PATH matches. -std=c++17 selects build mode; -O2 enables optimization; -Wall -Wextra enable warnings; -o a.exe names the executable. C++17 mode reports201703. A supporting compiler may report202002 for -std=c++20; the macro does not prove complete language/library conformance. If compilation fails, do not run a stale a.exe and mistake it for the new program.')),
 section('5. Input/output файлууд','5. Input/output files',
 p('Эхлээд a,b-г уншиж, дараа нийлбэрийг нь хэвлэнэ. Энэ жижиг дасгалд a,b нь -1000-аас1000 тул int хангалттай; том нийлбэрийн ерөнхий шаблон болгож бүү ойлго. Бүтэн программ:','Read a,b, then print their sum. In this small exercise a,b lie between -1000 and1000, so int is sufficient; this is not a universal type choice for large sums. Complete program:'),code(sumcode,'C++17'),
 p('a.in гэдэг text файлд 2 3 гэж бичээд хадгал. CMD дээр дараах нь compile амжилттай үед л ажиллуулна. a.exe нь программ; a.out нь гаралтын text файл.','Save2 3 in a text file named a.in. In CMD, the following runs only after successful compilation. a.exe is the program; a.out is an output text file.'),
 code('g++ -std=c++17 -O2 -Wall -Wextra main.cpp -o a.exe && a.exe < a.in > a.out 2> a.err\ntype a.out\n'),
 p('< нь stdin-ийг файлаас, > нь stdout-ийг файл руу чиглүүлнэ; байгаа гаралтын файлыг дарж бичнэ. 2> нь stderr-ийг тусад нь авна. Зөв хариу 5 болон шинэ мөр. Input файл ба executable-аа output файлтай ижил нэрлэж болохгүй.','< reads stdin from a file; > redirects stdout and overwrites an existing destination. 2> separates stderr. The expected output is5 and a newline. Never reuse the input or executable filename as the output destination.')),
 section('6. PowerShell ба UCRT64 Bash','6. PowerShell and UCRT64 Bash',
 p('PowerShell дээр < нь Bash/CMD шиг stdin redirect биш. Тоон текстийг Get-Content-аар pipe хийж болох ч encoding/newline өөрчлөгдөх боломжтой. Яг file redirection хэрэгтэй эхлэгчид CMD profile ашиглах, эсвэл PowerShell-оос CMD-г тодорхой дуудах нь ойлгомжтой.','In PowerShell, < is not Bash/CMD-style stdin redirection. Get-Content pipelines may transform encoding/newlines. For exact file redirection, use the CMD profile or explicitly invoke CMD from PowerShell.'),
 code('g++ -std=c++17 -O2 -Wall -Wextra main.cpp -o a.exe\nif ($LASTEXITCODE -eq 0) { cmd /c ".\\a.exe < a.in > a.out 2> a.err" }\nGet-Content .\\a.out\n'),
 p('Linux-ийн командтай ижил хэв маяг хүсвэл MSYS2 UCRT64 terminal-ийн Bash-ийг ашигла. VS Code-д profile тохируулахдаа MSYS2-ийн UCRT64 startup environment-ийг дагуул; зүгээр usr/bin/bash.exe нээхэд MSYS орчинд орох эрсдэлтэй. Эхлээд албан MSYS2 UCRT64 shortcut-аас дасгал хийж болно.','For Linux-like commands, use Bash in the MSYS2 UCRT64 terminal. A VS Code profile must preserve the UCRT64 startup environment; merely opening usr/bin/bash.exe can select the MSYS environment. You can first practice from the official MSYS2 UCRT64 shortcut.'),
 code('pwd\ncommand -v g++\ng++ --version\ng++ -std=c++17 -O2 -Wall -Wextra main.cpp -o a.exe && ./a.exe < a.in > a.out 2> a.err\ncat a.out\n')),
 section('7. Түгээмэл гацалт','7. Troubleshooting',
 listing(['g++ not found: compiler package, ucrt64/bin PATH, шинэ terminal-аа шалга.','main.cpp олдохгүй: cd/pwd-ээр замаа шалга; файл хадгалагдсан, .cpp өргөтгөлтэй эсэхийг хар.','Улаан underline ба build хоёр өөр: cppStandard нь IntelliSense; бодит build-ийн -std flag-ийг мөн тохируул.','DLL missing: сонгосон coherent toolchain-ийн bin PATH-даа байгаа эсэхийг шалга. Санамсаргүй DLL татаж хуулж болохгүй.','Программ хүлээгээд байвал input дутуу эсэхийг шалга; input-оо оруул эсвэл зөв a.in redirect хий.'],['g++ not found: check the compiler package, ucrt64/bin PATH and a new terminal.','main.cpp not found: inspect cwd with cd/pwd, save the file and verify its .cpp extension.','Red underlines and compilation differ: cppStandard controls IntelliSense; the build also needs the actual -std flag.','Missing DLL: check the coherent toolchain bin directory on PATH; do not download random DLL files.','A waiting program may need more input; supply it or redirect the correct a.in file.']),
 links([('VS Code: GCC on Windows','https://code.visualstudio.com/docs/cpp/config-mingw'),('MSYS2 environments','https://www.msys2.org/docs/environments/'),('MSYS2 full upgrades','https://www.msys2.org/docs/updating/'),('Microsoft documentation license','https://raw.githubusercontent.com/microsoft/vscode-docs/main/LICENSE.md')]))
],['introduction','cpp-terminal-ioi','cpp-devcpp'])
dev=lesson('cpp-devcpp','Dev-C++: compiler, стандарт, ажиллуулах','Dev-C++: compiler, standard and running','Bloodshed, Orwell, Embarcadero хувилбарууд; C++17 mode ба compiler шинэчлэхийн ялгаа.','Distinguish Bloodshed, Orwell and Embarcadero; C++17 mode versus upgrading a compiler.',[
 section('1. Ижил нэртэй өөр хувилбарууд','1. Different products with a shared name',
 p('Dev-C++ гэдэг нэр нэг ижил compiler гэсэн үг биш. Bloodshed нь анхны төсөл; Orwell нь fork; Embarcadero нь тэдгээрийн дараах fork. Албан Embarcadero release жагсаалтад v6.3 (2021-01-30) latest гэж байна; bundled compiler нь TDM-GCC9.2.0. Orwell-ийн 5.11 bundle нь TDM-GCC4.9.2 (2015). Хуучин IDE-ийн шинэ нэртэй installer бүрийг шинэ toolchain гэж үзэж болохгүй.','Dev-C++ does not identify one compiler. Bloodshed is the original project, Orwell a fork, and Embarcadero a later fork. The official Embarcadero release list marks v6.3 (2021-01-30) latest with TDM-GCC9.2.0. Orwell5.11 bundled TDM-GCC4.9.2 in2015. A differently branded installer does not necessarily contain a modern toolchain.'),
 dev_image(),
 links([('AsbakWiki: source image and attribution','https://commons.wikimedia.org/wiki/File:Devcpp5110.png'),('Image license: CC BY-SA3.0','https://creativecommons.org/licenses/by-sa/3.0/')]),
 diagram('Түүхэн fork-уудын схем; UI screenshot биш','Fork lineage; schematic, not a UI screenshot',[('Bloodshed',15,50),('Orwell',50,50),('Embarcadero',85,50)],[(0,1),(1,2)]),
 p('Энэ зааврын menu нэрс Embarcadero-ийн албан UI source-оор тулгагдсан; Windows дээр өөрийн capture хийсэн зураг биш. Version болон орчуулсан UI-гаас харагдах нэр бага зэрэг өөр байж болно.','Menu names below are checked against Embarcadero’s official UI source. They are not self-captured Windows screenshots; labels may differ by version/localization.')),
 section('2. Эхний файл ба товчнууд','2. First file and actions',
 p('File → New → Source File ашиглаад main.cpp нэрээр хадгал. .c гэж хадгалбал C compiler сонгогдож болно. Доорх программын include, main, stream output хэсгийг VS Code заавартай ижил утгаар уншина.','Create a Source File and save it as main.cpp. Saving as .c can select the C compiler. The include, main and stream output have the same meaning as in the VS Code guide.'),code(probe,'C++17'),
 p('Embarcadero-ийн shortcut: F9 Compile, F10 Run, F11 Compile & Run, F12 Rebuild All. Тодорхой IDE/version дээр өөр shortcut харагдвал Execute menu-ийн өөрийн бичгийг баримтал. Compile log дээр сонгосон compiler ба алдааг хар; build алдаатай байхад өмнөх executable-ийг ажиллуулахгүй.','Embarcadero shortcuts: F9 Compile, F10 Run, F11 Compile & Run, F12 Rebuild All. Follow the actual Execute menu if your version uses different shortcuts. Inspect the compiler and errors in the compile log; do not run an old executable after a failed build.')),
 section('3. C++17 mode тохируулах','3. Select C++17 mode',
 p('Tools → Compiler Options нээгээд Compiler set to configure дээр ашиглаж буй set-ээ сонго. General tab-ийн Add the following commands when calling the compiler талбарыг идэвхжүүлж -std=c++17 оруулж болно. Энэ нь source дахь #define биш, compiler-ийн argument. Settings tab-д language standard сонголт байгаа бол ижил flag-ийг давхар зөрүүлж нэмэхгүй. Project-ийн тусгай option глобал set-ийг дарж байгаа эсэхийг compile log-оор шалга.','Open Tools → Compiler Options and choose the active Compiler set to configure. In General, enable Add the following commands when calling the compiler and add -std=c++17. This is a compiler argument, not a source #define. If Settings has a language-standard selector, avoid conflicting duplicate flags. Inspect the compile log for project options overriding the global set.'),code('-std=c++17 -O2 -Wall -Wextra\n'),
 p('Rebuild хийгээд probe-оо ажиллуул: C++17 mode-д 201703 гарна. Энэ тоо нь сонгосон mode; бүрэн library conformance-ийн гэрчилгээ биш. TDM-GCC9.2-д C++17-ийг үндсэн зорилт болго. C++20-ийн бүх feature ажиллана гэж үзэхгүй; шинэ compiler дээр өөр flag, library шаардлагатай байж болно.','Rebuild and run the probe: C++17 mode reports201703. This reports the mode, not complete library conformance. Use C++17 as the baseline for TDM-GCC9.2. Do not assume full C++20 support; newer features may require a newer compiler and library.')),
 section('4. Flag нэмэх нь compiler шинэчлэх биш','4. A flag is not a compiler upgrade',
 p('GCC4.9-д -std=c++17 бичлээ гээд parser болон standard library нь шинэ болохгүй. Шинэ compiler хэрэгтэй бол албан maintained toolchain-ийг бүхлээр нь суулгаж, тусдаа compiler set үүсгэ. Programs дахь g++, gcc, make, gdb болон Directories дахь bin/include/lib нь нэг toolchain-д таарах ёстой. g++.exe ганцыг хуулж солих нь headers, libraries, DLL, debugger-ийг зөрүүлнэ.','Adding -std=c++17 to GCC4.9 cannot upgrade its parser or standard library. Install a coherent maintained toolchain and create a separate compiler set if you need a newer compiler. Programs (g++, gcc, make, gdb) and Directories (bin/include/lib) must agree. Replacing only g++.exe mismatches headers, libraries, DLLs and debugger.'),
 p('Эхлээд шинэ toolchain-аа өөрийн terminal-д g++ --version, language-mode probe, энгийн input/output программаар шалга. Дараа нь IDE-д тусдаа set холбож log дахь замыг батал. MSYS2-г Dev-C++-д нэг товчоор заавал холбогдоно гэж энэ заавар амлахгүй. Орчин үеийн default зам хэрэгтэй бол VS Code + MSYS2 UCRT64 зааврыг сонго.','First validate the new toolchain in its terminal using g++ --version, the language-mode probe and a simple input/output program. Then connect a separate IDE set and confirm its path in the log. This guide does not promise one-click MSYS2 integration into Dev-C++. For a current default workflow, use the VS Code + MSYS2 UCRT64 guide.')),
 section('5. Файлаас input өгөх','5. Read input from a file',
 p('Console нээгдээд хаагдах нь pause нэмэх шалтгаан биш. Existing terminal-оос executable-аа ажиллуулбал гаралт харагдана. Compile log-оос бодит .exe нэр, folder-ийг аваад CMD-д тэр folder руу ор.','A console closing does not require system("pause"). Run the executable from an existing terminal to keep output visible. Use the actual .exe name and directory from the compile log, then enter that directory in CMD.'),code('cd /d "C:\\CP Practice"\na.exe < a.in > a.out 2> a.err\ntype a.out\n'),
 p('a.exe гэдэг нь жишээ нэр; өөрийн build-ийн нэрээр солино. Тэмцээний input/output-д нэмэлт prompt, pause, debug stdout хэрэггүй. Grader function шаарддаг бодлогыг дурын main-тай standalone гэж бүү хөрвүүл.','a.exe is an example name; replace it with your build’s executable. Contest input/output needs no extra prompts, pause commands or debug stdout. A grader-function task must not be treated as an arbitrary standalone main program.'),
 links([('Official Dev-C++ releases','https://github.com/Embarcadero/Dev-Cpp/releases'),('Compiler Options UI source','https://github.com/Embarcadero/Dev-Cpp/blob/master/Source/CompOptionsFrm.dfm'),('Orwell original releases','https://sourceforge.net/projects/orwelldevcpp/files/Setup%20Releases/'),('Embarcadero project','https://www.embarcadero.com/free-tools/dev-cpp')]))
],['cpp-windows-vscode','cpp-terminal-ioi'])
ioi=lesson('cpp-terminal-ioi','Terminal: файл, compile/run, IOI Ubuntu','Terminal: files, compile/run and IOI Ubuntu','Bash-ийн cwd, ./a, stdin/stdout/stderr; IOI2026-ийн нийтэлсэн орчны мэдээлэл.','Bash cwd, ./a, stdin/stdout/stderr and the published IOI2026 environment.',[
 section('1. IOI-ийн орчин ба shell','1. IOI environment and shell',
 p('IOI2026-ийн албан Grading Equipment хуудсанд Ubuntu24.04 LTS, GCC13.3.0, GNOME Terminal3.52.0, Konsole23.08.5 гэж жагсаасан. Хуудас нь planned/minimum setup гэж тайлбарладаг тул яг эцсийн workstation image-ийг өөрөө туршсан баталгаа биш. Жил бүрийн compiler/VM, grading command-ийг тухайн тэмцээний заавраас дахин шалга.','The official IOI2026 Grading Equipment page lists Ubuntu24.04 LTS, GCC13.3.0, GNOME Terminal3.52.0 and Konsole23.08.5. It describes a planned/minimum setup, not an independently tested final workstation image. Check each edition’s compiler/VM and grading command in its own instructions.'),
 p('GNOME Terminal, Konsole нь terminal emulator; Bash нь shell; g++ нь compiler. Доорх command-ууд Bash-д зориулагдсан. Ubuntu гэдгээс terminal-ийн brand эсвэл shell-ийн яг хувилбарыг тааж болохгүй.','GNOME Terminal and Konsole are terminal emulators, Bash is a shell, and g++ is a compiler. Commands below are for Bash. Ubuntu alone does not establish the exact terminal brand or shell version.'),code('echo "$0"\nbash --version\ng++ --version\ncommand -v g++\n')),
 section('2. Folder үүсгээд нээх','2. Create and open a folder',
 p('pwd одоогийн folder-ийг харуулна. mkdir practice дотор нь шинэ folder үүсгэнэ. code practice editor нээхээс shell-ийн cwd-г солихгүй. cd practice нь shell-ийг тэр folder руу оруулна; code . нь одоо байгаа folder-ийг нээнэ.','pwd prints the current directory. mkdir practice creates a child directory. code practice opens the editor without changing the shell’s cwd. cd practice enters that directory; code . opens the current directory.'),code('pwd\nmkdir practice\ncode practice\ncd practice\npwd\ncode .\n'),
 p('Folder аль хэдийн байвал mkdir алдаа өгч болох ч байгаа folder-оо устгах хэрэггүй. ls-ээр шалгаад cd practice хий. Зайтай замыг quote хийнэ: cd "CP Practice". code байхгүй бол installed editor-ийн File → Open Folder ашиглаж болно. Ubuntu дээр системийн тохиргоог дур мэдэн өөрчлөхөөс өмнө тухайн суулгалтын албан VS Code зааврыг шалга; IOI workstation дээр software суулгах эрхтэй гэж бүү таамагла.','If the directory exists, mkdir may complain; do not delete it. Inspect with ls and enter it. Quote paths with spaces: cd "CP Practice". If code is unavailable, use the installed editor’s File → Open Folder. Check the official installation instructions before altering system setup; do not assume software-installation rights on an IOI workstation.')),
 section('3. Compile хийж executable үүсгэх','3. Compile an executable',
 p('main.cpp-аа хадгалсны дараа compile хийнэ. -o a гэж executable-аа ил тод нэрлэснээр default a.out executable-ийг output text файлаар дарж устгах алдаанаас зайлсхийнэ.','Save main.cpp before compiling. Naming the executable explicitly with -o a avoids overwriting the default a.out executable with output text.'),code('g++ -std=c++17 -O2 -Wall -Wextra main.cpp -o a\n./a\n'),
 p('./ нь одоогийн folder доторх executable-ийг заана; зөвхөн a гэвэл PATH-аас хайдаг тул олдохгүй байж болно. C++20 хэрэгтэй, compiler дэмжиж байвал -std=c++20 сонго. Тэмцээний бодит build command өөр байж болно. Include/main/I/O хэсэг нь ижил; дараах бүтэн программ хоёр жижиг тоог нэмнэ.','./ names an executable in the current directory; bare a searches PATH and may fail. Select -std=c++20 only if needed and supported. Actual contest build commands may differ. Include/main/I/O have the same meaning; this complete program adds two small integers.'),code(sumcode,'C++17')),
 section('4. a.in-ээс a.out руу','4. From a.in to a.out',
 p('a.in-д 2 3 болон шинэ мөр хадгал. Run нь compiler-оос тусдаа алхам. Bash дээр зөв command нь ./a < a.in > a.out; run a ... гэдэг universal command байхгүй.','Save2 3 and a newline in a.in. Running is a separate step from compilation. In Bash the command is ./a < a.in > a.out; there is no universal run a command.'),
 diagram('Файлын урсгал; a.out нь executable биш','File streams; a.out is not the executable',[('a.in',15,25),('./a',50,50),('a.out',85,25),('a.err',85,80)],[(0,1),(1,2),(1,3)]),
 code('g++ -std=c++17 -O2 -Wall -Wextra main.cpp -o a && ./a < a.in > a.out 2> a.err\ncat a.out\n'),
 p('&& нь compile амжилттай үед л run хийнэ. < stdin, > stdout, 2> stderr-ийг чиглүүлнэ. > нь байгаа файлыг эхлээд хоосолдог: ./a.out > a.out гэж executable-аа өөр дээр нь дарж болохгүй. Мөн ./a < a.in > a.in гэж input-оо устгаж болохгүй.','&& runs only after successful compilation. < redirects stdin, > stdout, and2> stderr. > truncates its destination first: never write ./a.out > a.out over the executable or ./a < a.in > a.in over the input.'),
 p('Жишээний утга literal хэвээр:','Literal example:'),code('2 3\n','Input'),code('5\n','Output')),
 section('5. Алдааг ялгах ба файл харьцуулах','5. Diagnose and compare',
 listing(['No such file: pwd, ls, зөв нэр, uppercase/lowercase-аа шалга; Linux case-sensitive.','Permission denied: executable үүссэн эсэх, зөв folder, compiler result-аа шалга. Хамгаалалтыг унтраах гэж бүү оролд.','Программ хүлээгээд байвал input дутуу эсвэл буруу файл нээсэн байж болно.','a.out хоосон байвал compiler log, exit status, a.err-ээ шалга; prompt-оо stdout-д нэмэхгүй.','Interactive бодлогод файл redirect хийснээр жинхэнэ judge орлохгүй; mock judge эсвэл өгсөн grader хэрэгтэй.'],['No such file: inspect pwd, ls, filenames and capitalization; Linux is case-sensitive.','Permission denied: verify a real executable, cwd and build result. Do not disable protections.','A waiting program may need more input or be reading the wrong file.','For empty a.out, inspect compiler output, exit status and a.err; do not add prompts to stdout.','Redirected files do not replace an interactive judge; use a mock judge or the supplied grader.']),code('cat a.err\ndiff -u expected.out a.out\n'),
 p('diff нь яг text ялгааг харуулна; judge-ийн whitespace tolerance-ийг өөрөө тааж болохгүй. Энэ командуудыг Linux Bash орчинд шалгана; энд Windows GUI эсвэл IOI VM ажиллуулсан гэж үзэхгүй.','diff shows exact text differences; do not guess a judge’s whitespace policy. These commands are validated in Linux Bash; this does not imply Windows GUI or IOI VM testing.'),
 links([('IOI2026 official environment','https://www.ioi2026.uz/grading-equipment'),('GCC language-mode macro','https://gcc.gnu.org/onlinedocs/cpp/Standard-Predefined-Macros.html'),('Bash redirections','https://www.gnu.org/software/bash/manual/html_node/Redirections.html'),('PowerShell stdin limitation','https://github.com/PowerShell/PowerShell/issues/19392')]))
],['cpp-windows-vscode','cpp-devcpp','interactive-communication'])
def practice_quiz(id,qmn,qen,omn,oen,ans,emn,een):
 def make(question,options,explanation):return {'type':'quiz','quizId':id,'question':question,'options':[{'id':str(i),'text':text}for i,text in enumerate(options)],'answerId':str(ans),'explanation':explanation}
 return make(qmn,omn,emn),make(qen,oen,een)
for doc,block in [(win,practice_quiz('windows-shell-input','PowerShell дээр a.in-ийг яг stdin болгох энэ зааврын тохирох арга аль вэ?','Which method in this guide supplies a.in as stdin from PowerShell?',['CMD profile эсвэл cmd /c-г тодорхой дуудах','< нь бүх shell-д ижил','Input-ийг C++ source руу paste хийх'],['Use the CMD profile or invoke cmd /c explicitly','< works identically in every shell','Paste input into the C++ source'],0,'PowerShell-ийн < нь Bash/CMD шиг stdin redirect биш. Яг файлыг дамжуулахдаа CMD-г тодорхой ашигла.','PowerShell does not provide Bash/CMD-style < stdin redirection. Invoke CMD explicitly for the file.')),(dev,practice_quiz('devcpp-compiler-flag','Хуучин GCC-д -std=c++17 нэмэх нь compiler шинэчлэх үү?','Does adding -std=c++17 upgrade an old GCC compiler?',['Үгүй; parser/library өөрчлөгдөхгүй','Тийм; бүх feature суулгана','Зөвхөн IDE theme солиход болно'],['No; the parser/library do not change','Yes; it installs every feature','Only after changing the IDE theme'],0,'Flag нь байгаа compiler-ийн дэмжсэн mode-ийг сонгоно. Шинэ feature-д coherent toolchain шинэчлэх хэрэгтэй.','A flag selects a mode supported by the installed compiler. New features may require a coherent newer toolchain.')),(ioi,practice_quiz('bash-output-name','./a.out > a.out яагаад буруу вэ?','Why is ./a.out > a.out wrong?',['Shell output файлыг эхлээд хоосолж executable-ийг дарна','Bash C++ ажиллуулдаггүй','Compiler үргэлж prompt шаарддаг'],['The shell truncates the executable as its output destination','Bash cannot run C++ programs','The compiler always needs a prompt'],0,'Executable-аа -o a гэж тусад нь нэрлээд ./a < a.in > a.out хэрэглэ. Input ба output мөн тусдаа байна.','Name the executable separately with -o a, then use ./a < a.in > a.out. Keep input and output files distinct too.'))]:
 doc['sections'].append({'title':'Өөрийгөө шалгах','blocks':[block[0]]});doc['translations']['en']['sections'].append({'title':'Check your understanding','blocks':[block[1]]})
dev['priorityLevel']='medium'
def polish_text(value):
 if isinstance(value,list):
  for item in value:polish_text(item)
 elif isinstance(value,dict):
  for key,item in list(value.items()):
   if key in ['text','caption','question','explanation','summary']and isinstance(item,str)and value.get('type')!='code':
    for old,new in [('Windows10','Windows 10'),('Windows11','Windows 11'),('Ubuntu24.04','Ubuntu 24.04'),('GCC13.3.0','GCC 13.3.0'),('TDM-GCC9.2.0','TDM-GCC 9.2.0'),('TDM-GCC4.9.2','TDM-GCC 4.9.2'),('GCC9.2','GCC 9.2'),('GCC4.9','GCC 4.9'),('Orwell5.11','Orwell 5.11'),('GNOME Terminal3.52.0','GNOME Terminal 3.52.0'),('Konsole23.08.5','Konsole 23.08.5'),('reports201703','reports 201703'),('report202002','report 202002'),('Save2 3','Save 2 3'),('output is5','output is 5'),('between -1000 and1000','between -1000 and 1000'),('-1000-аас1000','-1000-аас 1000')]:item=item.replace(old,new)
    value[key]=item
   elif key not in ['tex','assetPath','url']:polish_text(item)
for doc in [win,dev,ioi]:polish_text(doc)
(R/'audit/course100-v2/setup-tutorials.json').write_text(json.dumps([win,dev,ioi],ensure_ascii=False,indent=2)+'\n')
